"""Generates `panel/crates/model/src/routing/tables.rs`: the Unicode tables behind Python's
`str.encode("idna")` (RFC 3490 nameprep through CPython's `stringprep`, Unicode 3.2) and the code
points `str.isdigit()` accepts that `int()` refuses.

Run with external Python 3.13 on ams-test (never inside the native panel image):

    python3.13 -I \
        panel/crates/model/tests/fixtures/generators/gen_tables.py panel/crates/model/src/routing/tables.rs
"""
import stringprep
import sys
import unicodedata


def ranges(predicate):
    out = []
    start = None
    for cp in range(0x110000 + 1):
        inside = cp <= 0x10FFFF and not (0xD800 <= cp <= 0xDFFF) and predicate(chr(cp))
        if inside and start is None:
            start = cp
        elif not inside and start is not None:
            out.append((start, cp - 1))
            start = None
    return out


def rust_str(text):
    return '"' + "".join(ch if 0x20 <= ord(ch) < 0x7F and ch not in '"\\' else f"\\u{{{ord(ch):x}}}" for ch in text) + '"'


def table(name, doc, items):
    lines = [f"/// {doc}", f"pub(crate) const {name}: &[(u32, u32)] = &["]
    row = []
    for start, end in items:
        row.append(f"(0x{start:x}, 0x{end:x}),")
        if len(row) == 6:
            lines.append("    " + " ".join(row))
            row = []
    if row:
        lines.append("    " + " ".join(row))
    lines.append("];")
    return "\n".join(lines)


def prohibited(ch):
    return (stringprep.in_table_c12(ch) or stringprep.in_table_c22(ch) or stringprep.in_table_c3(ch)
            or stringprep.in_table_c4(ch) or stringprep.in_table_c5(ch) or stringprep.in_table_c6(ch)
            or stringprep.in_table_c7(ch) or stringprep.in_table_c8(ch) or stringprep.in_table_c9(ch))


def main():
    mapping = []
    for cp in range(0x110000):
        if 0xD800 <= cp <= 0xDFFF:
            continue
        ch = chr(cp)
        if stringprep.in_table_b1(ch):
            continue
        mapped = stringprep.map_table_b2(ch)
        if mapped != ch.lower():
            mapping.append((cp, mapped))
    parts = [
        "//! Generated by `tests/fixtures/generators/gen_tables.py` from CPython "
        + sys.version.split()[0] + " (`stringprep`, `unicodedata` "
        + unicodedata.unidata_version + "); do not edit by hand.",
        "",
        table("B1", "RFC 3454 table B.1: mapped to nothing by nameprep.", ranges(stringprep.in_table_b1)),
        "",
        "/// Nameprep's table B.2 mapping where it differs from Python's `str.lower()` (sorted).",
        "pub(crate) const B2_EXCEPTIONS: &[(u32, &str)] = &[",
        *[f"    (0x{cp:x}, {rust_str(text)})," for cp, text in mapping],
        "];",
        "",
        table("PROHIBITED", "RFC 3454 tables C.1.2, C.2.2 and C.3–C.9 (Unicode 3.2): refused by nameprep.",
              ranges(prohibited)),
        "",
        table("RAND_AL", "RFC 3454 table D.1: bidirectional R or AL (Unicode 3.2).", ranges(stringprep.in_table_d1)),
        "",
        table("BIDI_L", "RFC 3454 table D.2: bidirectional L (Unicode 3.2).", ranges(stringprep.in_table_d2)),
        "",
        table("DIGIT_NOT_DECIMAL", "`str.isdigit()` but not `str.isdecimal()`: digits Python's `int()` refuses.",
              ranges(lambda ch: ch.isdigit() and not ch.isdecimal())),
        "",
    ]
    with open(sys.argv[1], "w", encoding="utf-8") as handle:
        handle.write("\n".join(parts))
    print(len(mapping), "mappings")


if __name__ == "__main__":
    main()
